import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SRC = join(ROOT, "src");
const CONTENT_OUT = join(ROOT, "dist", "content.bundle.js");
const SW_OUT = join(ROOT, "dist", "service-worker.bundle.js");

const CONTENT_MODULES = [
  "core/charsets.js",
  "core/analyzer.js",
  "core/flow.js",
  "core/typography.js",
  "core/scheduler.js",
  "core/patch-store.js",
  "core/errors.js",
  "adapters/registry.js",
  "core/settings.js",
  "core/page-style.js",
  "core/engine.js",
  "content/content.js",
];

const SW_MODULES = [
  "core/charsets.js",
  "core/analyzer.js",
  "core/font-names.js",
  "core/bundled-fonts.js",
  "core/errors.js",
  "adapters/registry.js",
  "core/settings.js",
  "core/custom-fonts.js",
  "background/service-worker.js",
];

function resolveDep(fromId, dep) {
  const parts = fromId.split("/");
  parts.pop();
  for (const seg of dep.replace(/\.js$/, "").split("/")) {
    if (seg === "." || seg === "") continue;
    if (seg === "..") parts.pop();
    else parts.push(seg);
  }
  return "./" + parts.join("/") + ".js";
}

function transform(id, source) {
  const exported = [];
  let body = source;

  body = body.replace(/^import\s*\{([^}]+)\}\s*from\s*["']([^"']+)["'];?[ \t]*$/gm, (_, names, dep) => {
    const list = names
      .split(",")
      .map((n) => n.trim())
      .filter(Boolean)
      .map((n) => {
        const m = n.match(/^(\w+)\s+as\s+(\w+)$/);
        return m ? `${m[1]}: ${m[2]}` : n;
      })
      .join(", ");
    return `const { ${list} } = __req(${JSON.stringify(resolveDep(id, dep))});`;
  });

  body = body.replace(/^export\s+default\b.*$/gm, () => {
    throw new Error(`default export is not supported (${id})`);
  });
  body = body.replace(/^export\s+const\s+(\w+)/gm, (_, name) => {
    exported.push(name);
    return `const ${name}`;
  });
  body = body.replace(/^export\s+function\s+(\w+)/gm, (_, name) => {
    exported.push(name);
    return `function ${name}`;
  });
  body = body.replace(/^export\s+class\s+(\w+)/gm, (_, name) => {
    exported.push(name);
    return `class ${name}`;
  });
  if (/^export\s/m.test(body)) throw new Error(`unsupported export form in ${id}`);

  const tail = exported.map((n) => `__exp.${n} = ${n};`).join("\n  ");
  return `__def(${JSON.stringify("./" + id)}, function (__req, __exp) {\n${body}\n  ${tail}\n});`;
}

function buildBundle(modules, entry, outPath, label) {
  const header = `/* RTL Atelier — ${label} (generated by scripts/bundle.js). Do not edit. */
(function () {
  "use strict";
  var __mods = {};
  var __cache = {};
  function __def(id, factory) {
    __mods[id] = factory;
  }
  function __req(id) {
    if (__cache[id]) return __cache[id];
    var factory = __mods[id];
    if (!factory) throw new Error("RTL Atelier: unknown module " + id);
    var exports = {};
    __cache[id] = exports;
    factory(__req, exports);
    return exports;
  }
`;
  const footer = `  __req(${JSON.stringify(entry)});\n})();\n`;
  const parts = modules.map((id) => transform(id, readFileSync(join(SRC, id), "utf8")));
  const code = header + parts.join("\n") + footer;

  // Syntax validation
  new Function(code);

  // Runtime execution validation with mock browser APIs
  if (label.includes("service worker")) {
    const mockChrome = {
      runtime: {
        onInstalled: { addListener() {} },
        onStartup: { addListener() {} },
        onMessage: { addListener() {} },
        sendMessage() {},
      },
      storage: {
        local: { get: async () => ({}), set: async () => {} },
        session: { get: async () => ({}), set: async () => {} },
      },
      tabs: {
        onRemoved: { addListener() {} },
        query: async () => [],
        get: async () => null,
        sendMessage: async () => {},
      },
      action: {
        setBadgeText() {},
        setBadgeBackgroundColor() {},
      },
      commands: {
        onCommand: { addListener() {} },
      },
    };
    new Function("chrome", code)(mockChrome);
  }

  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, code, "utf8");
  console.log(`bundle: ${modules.length} modules -> ${outPath.replace(ROOT + "\\", "")} (${code.length} bytes)`);
}

buildBundle(CONTENT_MODULES, "./content/content.js", CONTENT_OUT, "content bundle");
buildBundle(SW_MODULES, "./background/service-worker.js", SW_OUT, "service worker bundle");
